/** Full text from the rules repository; costs distinguish expenditures from discounts and rewards. */
internal object CanonicalAbilityDefaults {
    private data class Values(val name: String, val effect: String, val cost: String,
        val action: String, val range: String, val duration: String, val prerequisites: String)
    private val values by lazy { powers() + professionPowers() + magic() + ashes() + runes() }
    fun apply(entry: CatalogEntry): CatalogEntry {
        val value = values[entry.id] ?: return entry
        return entry.copy(name = value.name, summary = value.effect, mechanicalEffect = value.effect,
            cost = value.cost, action = value.action, range = value.range, duration = value.duration,
            prerequisites = value.prerequisites.takeIf(String::isNotBlank)?.let(::listOf).orEmpty())
    }
